import json
import os
import subprocess
import tempfile
from pathlib import Path

from ..errors import VariationError, require
from ..imaging import read_image, sha256
from .base import GeneratedImage, Provider, require_ready

CODEX_IMAGES_BASE_URL = "http://127.0.0.1:10100/v1"
CODEX_IMAGE_MODELS = {"gpt-image-2.6-sunburst", "gpt-image-2.6-flare"}


class HostFileProvider(Provider):
    """Import a real image generated by a selected host tool outside this process."""

    environment = "builtin"

    def __init__(self, image_path):
        self.image_path = Path(image_path)

    def generate(self, prompt, plan, reference_bytes=None):
        require_ready(plan)
        require(self.image_path.is_file(), "BUILTIN_UNAVAILABLE", "请先使用已选宿主工具生成本单元图片")
        data = self.image_path.read_bytes()
        read_image(data)
        return GeneratedImage(
            data, public_metadata={"route_used": plan["api_route"], "source": "host_file_import"}
        )


class CodexSkillProvider(Provider):
    """Use the user-selected local codex-image Skill, without inspecting OAuth secrets."""

    environment = "builtin"

    def __init__(
        self,
        script_path,
        expected_script_sha256,
        quality="low",
        timeout=240,
        *,
        base_url=CODEX_IMAGES_BASE_URL,
    ):
        self.script = Path(script_path).expanduser().resolve()
        require(
            self.script.is_file() and sha256(self.script.read_bytes()) == expected_script_sha256,
            "BUILTIN_UNAVAILABLE",
            "本地生图 Skill 脚本与已验证版本不符",
        )
        require(
            quality in {"low", "medium", "high", "xhigh", "max", "auto"}, "INVALID_INPUT", "无效图片质量参数"
        )
        self.quality, self.timeout = quality, timeout
        self.base_url = base_url.rstrip("/")

    def generate(self, prompt, plan, reference_bytes=None):
        require_ready(plan)
        route = "images/edits" if reference_bytes else "images/generations"
        configured_route = plan["api_route"]
        if reference_bytes:
            configured_route = plan.get("reference_api_route") or configured_route
        require(
            plan["model_id"] in CODEX_IMAGE_MODELS and configured_route == f"codex.{route.replace('/', '.')}",
            "MODEL_CAPABILITY_UNSUPPORTED",
            "请选择 codex-image 0.4.0 支持的 GPT Image 2.6 型号与已验证 Images 路由",
        )
        configured_env = os.environ.get("CODEX_IMAGE_BASE_URL", "").strip().rstrip("/")
        require(
            not configured_env or configured_env == self.base_url,
            "MODEL_CAPABILITY_UNSUPPORTED",
            "Codex Images 端点与能力档案不一致",
        )
        with tempfile.TemporaryDirectory(prefix="image-variations-") as tmp:
            tmp = Path(tmp)
            prompt_path = tmp / "prompt.txt"
            prompt_path.write_text(prompt)
            args = [
                "node",
                str(self.script),
                "--prompt-file",
                str(prompt_path),
                "--image-model",
                plan["model_id"],
                "--size",
                plan["provider_parameters"]["size"],
                "--quality",
                self.quality,
                "--format",
                "png",
                "--out-dir",
                str(tmp),
                "--timeout",
                str(self.timeout * 1000),
            ]
            if plan.get("requested_aspect_ratio"):
                args.extend(["--aspect-ratio", plan["requested_aspect_ratio"]])
            if reference_bytes:
                ref = tmp / "reference.png"
                # Re-encode for extension/MIME correctness, retaining all pixels.
                from ..imaging import png_bytes

                ref.write_bytes(png_bytes(read_image(reference_bytes)["image"]))
                args.extend(["--reference-image", str(ref)])
            try:
                process = subprocess.run(
                    args,
                    env={**os.environ, "CODEX_IMAGE_BASE_URL": self.base_url},
                    capture_output=True,
                    timeout=self.timeout + 30,
                    check=False,
                )
            except (subprocess.TimeoutExpired, OSError):
                raise VariationError("PROVIDER_TIMEOUT", "本地生图调用未确认完成，请核对后再试") from None
            # Never echo captured stdout/stderr or raw provider errors.
            if process.returncode:
                try:
                    failed = json.loads(process.stdout)
                except (ValueError, TypeError):
                    failed = None
                known_errors = {
                    "NATIVE_RESOLUTION_VALIDATION_FAILED",
                    "ASPECT_RATIO_VALIDATION_FAILED",
                    "QUALITY_VALIDATION_FAILED",
                    "FORMAT_VALIDATION_FAILED",
                    "PROVIDER_METADATA_MISMATCH",
                }
                if (
                    process.returncode == 2
                    and isinstance(failed, dict)
                    and failed.get("ok") is False
                    and failed.get("code") in known_errors
                ):
                    dimensions = {
                        key: failed.get(field)
                        for key, field in (("width", "actualWidth"), ("height", "actualHeight"))
                    }
                    if not all(type(value) is int and 0 < value <= 32768 for value in dimensions.values()):
                        dimensions = None
                    reported_quality = failed.get("reportedQuality")
                    if reported_quality not in {"low", "medium", "high", "xhigh", "max", "auto"}:
                        reported_quality = None
                    raise VariationError(
                        failed["code"],
                        "OpenCodex 原始图片或返回质量未满足本次请求",
                        details={
                            "actual_native_dimensions": dimensions,
                            "reported_quality": reported_quality,
                        },
                    )
                raise VariationError(
                    "BUILTIN_GENERATION_FAILED", "本地 codex-image 调用失败；检查登录状态或工具服务"
                )
            try:
                payload = json.loads(process.stdout)
                require(
                    isinstance(payload, dict)
                    and payload.get("requestedImageModel") == plan["model_id"]
                    and payload.get("route") == route
                    and payload.get("reportedImageModel") in (None, plan["model_id"]),
                    "MODEL_CAPABILITY_UNSUPPORTED",
                    "本地工具返回的模型或路由与尺寸计划不一致",
                )
                output = Path(payload.get("path", payload.get("output_path", ""))).resolve()
                require(
                    payload.get("ok") is True and output.is_relative_to(tmp.resolve()) and output.is_file(),
                    "BUILTIN_GENERATION_FAILED",
                    "本地工具未返回有效图片文件",
                )
                data = output.read_bytes()
            except (ValueError, TypeError):
                raise VariationError("BUILTIN_GENERATION_FAILED", "本地工具返回无法解析") from None
            read_image(data)
            metadata = {"route_used": configured_route, "tool": "codex-image"}
            if isinstance(payload.get("revisedPrompt"), str):
                metadata["returned_prompt_sha256"] = sha256(payload["revisedPrompt"].encode())
            return GeneratedImage(data, public_metadata=metadata)
